/* ═══════════════════════════════════════════════════════════════════════════
   GROUPS — Sub-teams within an org
   ═══════════════════════════════════════════════════════════════════════════ */

const orgGroups   = {};  // populated at startup via _loadAllStores()
const orgNotes    = {};
const orgMessages = {};

function noteId()  { return 'n_'   + generateId(); }
function msgId()   { return 'm_'   + generateId(); }
function groupId() { return 'grp_' + generateId(); }

/* ── Create group ─────────────────────────────────────────────────────────── */
app.post('/api/groups/create', requireAuth, (req, res) => {
  const code = req.iqSession.orgCode;
  const { name, description, memberIds, leadIds } = req.body;
  if (!name) return res.status(400).json({ error: 'name required' });
  if (!_isLeader(code, req.iqSession.userId) && orgUsers[code]?.[req.iqSession.userId]?.role !== 'superadmin') {
    return res.status(403).json({ error: 'Only a leader can create groups.' });
  }
  if (!orgGroups[code]) orgGroups[code] = [];
  const group = { id: groupId(), name, description: description || '', memberIds: memberIds || [], leadIds: leadIds || [], goals: [], traits: [], copilotEnabled: false, createdAt: new Date().toISOString() };
  orgGroups[code].push(group);
  scheduleSave();
  res.json({ ok: true, group });
});

/* ── List groups for org (filtered by memberId if provided) ─────────────── */
app.get('/api/groups', requireAuth, (req, res) => {
  const orgCode = req.iqSession.orgCode;   // own org only — never read another org's groups
  const { memberId } = req.query;
  let groups = orgGroups[orgCode] || [];
  if (memberId) {
    groups = groups.filter(g => g.memberIds.includes(memberId) || g.leadIds.includes(memberId));
  }
  res.json({ groups });
});

/* ── Update group ────────────────────────────────────────────────────────── */
app.put('/api/groups/:groupId', requireAuth, (req, res) => {
  const code = req.iqSession.orgCode;
  const { name, description, memberIds, leadIds } = req.body;
  if (!_isLeader(code, req.iqSession.userId) && orgUsers[code]?.[req.iqSession.userId]?.role !== 'superadmin') {
    return res.status(403).json({ error: 'Only a leader can edit groups.' });
  }
  const groups = orgGroups[code] || [];   // scoped to the caller's own org — never another's
  const g      = groups.find(g => g.id === req.params.groupId);
  if (!g) return res.status(404).json({ error: 'Group not found' });
  if (name        !== undefined) g.name        = name;
  if (description !== undefined) g.description = description;
  if (memberIds   !== undefined) g.memberIds   = memberIds;
  if (leadIds     !== undefined) g.leadIds     = leadIds;
  scheduleSave();
  res.json({ ok: true, group: g });
});

/* ── Set a group's GOALS & TRAITS (the TEAM frame) ────────────────────────────
   Only a LEAD of the group (or an admin/superadmin) may set its aims — being a
   member is not enough. This is the membership-vs-leadership distinction: a coach
   leads "Quarterbacks" (can set goals) but is only a member of "Staff" (cannot). */
app.put('/api/groups/:groupId/aims', requireAuth, (req, res) => {
  const { orgCode, userId } = req.iqSession;
  const code   = orgCode;
  const groups = orgGroups[code] || [];
  const g      = groups.find(g => g.id === req.params.groupId);
  if (!g) return res.status(404).json({ error: 'Group not found' });

  const isLead  = (g.leadIds || []).includes(userId);
  const isAdmin = orgUsers[code]?.[userId]?.role === 'superadmin' || _userHasPerm(code, userId, 'manage_goals');
  if (!isLead && !isAdmin) {
    return res.status(403).json({ error: 'Only a lead of this group can set its goals and traits.' });
  }

  const clean = arr => Array.isArray(arr)
    ? [...new Set(arr.map(s => String(s).trim()).filter(Boolean))].slice(0, 20)
    : undefined;
  const goals  = clean(req.body.goals);
  const traits = clean(req.body.traits);
  if (goals  !== undefined) g.goals  = goals;
  if (traits !== undefined) g.traits = traits;
  scheduleSave();
  res.json({ ok: true, group: g });
});

/* ── PUT /api/groups/:groupId/copilot-settings — lead enables/disables Copilot ─
   The real consent gate: no analysis happens unless the lead turns it on. */
app.put('/api/groups/:groupId/copilot-settings', requireAuth, (req, res) => {
  const { orgCode, userId } = req.iqSession;
  const code = orgCode;
  const g    = (orgGroups[code] || []).find(g => g.id === req.params.groupId);
  if (!g) return res.status(404).json({ error: 'Group not found' });
  const isLead  = (g.leadIds || []).includes(userId);
  const isAdmin = orgUsers[code]?.[userId]?.role === 'superadmin' || _userHasPerm(code, userId, 'manage_settings');
  if (!isLead && !isAdmin) return res.status(403).json({ error: 'Only a lead can change Copilot settings.' });
  if (typeof req.body.enabled === 'boolean') g.copilotEnabled = req.body.enabled;
  scheduleSave();
  res.json({ ok: true, copilotEnabled: !!g.copilotEnabled });
});

/* ── GET /api/groups/:groupId/copilot — the Group Copilot (coach for the LEAD) ─
   Positioned as "help the group reach its stated goals", NOT "monitoring".
   SIGNALS-FIRST (participation / activity / goal signals — not message content),
   AGGREGATE-ONLY (advice, never naming or exposing individuals), DIRECTIONAL
   language (no scores). Through the AI gateway + privacy gate. Lead-only, and
   only runs when the lead has enabled the Copilot for the group. */
app.get('/api/groups/:groupId/copilot', requireAuth, async (req, res) => {
  const { orgCode, userId } = req.iqSession;
  const code = orgCode;
  const g    = (orgGroups[code] || []).find(g => g.id === req.params.groupId);
  if (!g) return res.status(404).json({ error: 'Group not found' });

  const isLead  = (g.leadIds || []).includes(userId);
  const isAdmin = orgUsers[code]?.[userId]?.role === 'superadmin' || _userHasPerm(code, userId, 'view_analytics');
  if (!isLead && !isAdmin) return res.status(403).json({ error: 'Only a lead of this group can use the Copilot.' });

  if (!g.copilotEnabled) return res.json({ ok: true, enabled: false });

  const memberIds = [...new Set([...(g.memberIds || []), ...(g.leadIds || [])])].filter(id => id !== userId);
  const now    = Date.now();
  const WEEK   = 7 * 86400000;

  // ── SIGNALS (no message content) ──────────────────────────────────────────
  let active7 = 0, activePrev = 0;            // members active this week / prior week
  let quietCount = 0;                          // became/stayed quiet (10+ days)
  let moodSum = 0, moodCnt = 0;
  memberIds.forEach(id => {
    const u = orgUsers[code]?.[id]; if (!u) return;
    const cks = memberCheckins[userKey(code, id)] || memberCheckins[memberKey(code, u.name || '')] || [];
    let a7 = false, aPrev = false, lastTs = null;
    cks.forEach(c => {
      const t = new Date(c.ts || c.date).getTime(); if (isNaN(t)) return;
      lastTs = Math.max(lastTs || 0, t);
      if (now - t < WEEK) a7 = true;
      else if (now - t < 2 * WEEK) aPrev = true;
      if (c.mood != null && now - t < 2 * WEEK) { moodSum += Number(c.mood); moodCnt++; }
    });
    if (a7) active7++;
    if (aPrev) activePrev++;
    const days = lastTs ? Math.floor((now - lastTs) / 86400000) : null;
    if (days === null || days >= 10) quietCount++;
  });

  // Group message volume (count only — never content) this week vs prior
  let msg7 = 0, msgPrev = 0;
  Object.values(orgMessages).forEach(m => {
    if (m.orgCode !== code || m.toType !== 'group' || m.toId !== g.id) return;
    const t = new Date(m.createdAt).getTime(); if (isNaN(t)) return;
    if (now - t < WEEK) msg7++; else if (now - t < 2 * WEEK) msgPrev++;
  });

  const total       = memberIds.length;
  const participation = total ? Math.round((active7 / total) * 100) : 0;
  const recentAct   = active7 + msg7;
  const priorAct    = activePrev + msgPrev;
  const engagementTrend = priorAct === 0 ? (recentAct > 0 ? 'Increasing' : 'Quiet')
    : recentAct > priorAct * 1.15 ? 'Increasing'
    : recentAct < priorAct * 0.85 ? 'Decreasing' : 'Steady';

  // Directional health (no score)
  const health = total === 0 ? 'No members yet'
    : participation >= 70 ? 'Sustaining'
    : participation >= 40 ? 'Holding'
    : 'Needs attention';
  const healthColor = health === 'Sustaining' ? 'green' : health === 'Holding' ? 'yellow' : 'red';

  // Goal progress (directional, heuristic until Phase 2 goal-progress signals)
  const goalProgress = !(g.goals && g.goals.length) ? 'No goals set'
    : participation >= 70 && engagementTrend !== 'Decreasing' ? 'Strong'
    : participation >= 40 ? 'Moderate' : 'Early';

  // ── AI: actions / prompts / reflection — from SIGNALS + goals/traits only ──
  const signalBrief = [
    `Group: ${g.name} (${total} members).`,
    g.goals?.length  ? `Goals: ${g.goals.join('; ')}.`   : 'Goals: none set.',
    g.traits?.length ? `Traits: ${g.traits.join(', ')}.` : 'Traits: none set.',
    `Participation this week: ${participation}% (${active7}/${total}).`,
    `Engagement trend: ${engagementTrend}.`,
    `Members who have gone quiet (10+ days): ${quietCount}.`,
    moodCnt ? `Recent average mood: ${Math.round((moodSum / moodCnt) * 10) / 10}/5.` : 'Mood: no recent data.',
    `Goal progress (directional): ${goalProgress}.`,
  ].join('\n');

  const system = [
    `You are the IntelliQ Group Copilot — a coach for the group's LEAD. Your job is to help the group move toward its stated goals. You are NOT a monitor and you do not surveil members.`,
    privacy.GATE_DIRECTIVE,
    `Hard rules: speak in AGGREGATE only — never name or single out an individual. Give the lead ADVICE, not exposure. Use directional language, never scores. Tie everything to the group's goals and traits.`,
    _worldviewDirective(code),
    _domainDirective(code),
  ].filter(Boolean).join('\n\n');

  const user = [
    'SIGNALS (counts and trends only — no message content):',
    signalBrief,
    '',
    'Return ONLY JSON: {"actions":["1-3 aggregate suggested actions for the lead, e.g. \'Some members have gone quiet — reach out personally\'"],"prompts":["2-3 discussion prompts derived from the group goals/traits the lead could post"],"reflection":"one short weekly reflection: what may be helping vs slowing progress toward the goals"}',
  ].join('\n');

  let out = null;
  try {
    out = await ai.completeJSON({ tier: 'reason', system, user, maxTokens: 500, schema: ['actions'] });
  } catch (err) {
    console.warn('[group-copilot] AI error:', err.message);
  }

  res.json({
    ok: true,
    enabled:   true,
    groupName: g.name,
    health, healthColor,
    participation,
    goalProgress,
    engagementTrend,
    hasGoals:  !!(g.goals && g.goals.length),
    actions:   Array.isArray(out?.actions) ? out.actions.slice(0, 3)
               : (quietCount > 0 ? [`${quietCount} member(s) have become less active — consider reaching out personally to see how they're doing.`] : []),
    prompts:   Array.isArray(out?.prompts) ? out.prompts.slice(0, 3) : [],
    reflection: out?.reflection || null,
  });
});

/* ── Delete group ─────────────────────────────────────────────────────────── */
app.delete('/api/groups/:groupId', requireAuth, (req, res) => {
  const code = req.iqSession.orgCode;
  if (!_isLeader(code, req.iqSession.userId) && orgUsers[code]?.[req.iqSession.userId]?.role !== 'superadmin') {
    return res.status(403).json({ error: 'Only a leader can delete groups.' });
  }
  if (!orgGroups[code]) return res.status(404).json({ error: 'Org not found' });
  orgGroups[code] = orgGroups[code].filter(g => g.id !== req.params.groupId);
  scheduleSave();
  res.json({ ok: true });
});

/* ═══════════════════════════════════════════════════════════════════════════
   NOTES — Private / Shared / Anonymous
   ═══════════════════════════════════════════════════════════════════════════ */

/* ── Create note ─────────────────────────────────────────────────────────── */
app.post('/api/notes', requireAuth, async (req, res) => {
  // Identity comes from the SESSION, never the body — a note is always authored by the caller,
  // in the caller's own org (no forging an author or writing into another org).
  const orgCode = req.iqSession.orgCode;
  const authorId = req.iqSession.userId;
  const authorName = orgUsers[orgCode]?.[authorId]?.name || '';
  const { content, type, tag, groupId: gid, orgMode, orgName, goals } = req.body;
  if (!content || !type) return res.status(400).json({ error: 'missing fields' });

  const id   = noteId();
  const note = {
    id, orgCode: orgCode.toLowerCase().trim(),
    groupId: gid || null,
    authorId, authorName,
    content, type,
    tag: tag || null,
    // Phase 1: classify sensitivity at write time so the privacy gate can act
    // on it later (private may inform AI reasoning, never be revealed).
    sensitivity: privacy.classifyText(content, { type, tag }),
    createdAt: new Date().toISOString(),
    aiResponse: null,
  };
  orgNotes[id] = note;
  // One home — mirror the note into the Library right away (idempotent), so a note made in the
  // legacy screen shows up in the Library too. Never throws the request.
  try { _noteToLibrary(note.orgCode, note); } catch (_) {}

  const shouldGetAIResponse = type === 'private' || type === 'anonymous' || type === 'shared';
  if (shouldGetAIResponse) {
    const prompts = {
      private:   `You are IntelliQ, a private AI companion. Someone has written a private note — only they and you see this. Respond with 1-2 sentences: acknowledge what they've written with genuine care, and if useful, offer one thought or gentle prompt to go deeper. Be warm and human, not clinical.`,
      shared:    `You are IntelliQ. Someone has written a note they're sharing with their group. Acknowledge it briefly (1 sentence) and note anything that might be useful context for their goals or development. Max 2 sentences.`,
      anonymous: `You are IntelliQ. Someone has posted an anonymous note to their group. Acknowledge it (1 sentence). This response is shown only to the author — not the group. Max 2 sentences.`,
    };
    const userMsg = goals?.goal ? `Their goal: "${goals.goal}"\n\nNote: ${content}` : `Note: ${content}`;
    try {
      const response = await client.messages.create({
        model: 'claude-haiku-4-5-20251001', max_tokens: 100,
        system: [prompts[type] || prompts.private, _worldviewDirective(note.orgCode), _domainDirective(note.orgCode, { userId: authorId }), _memberValuesDirective(note.orgCode, authorId)].filter(Boolean).join('\n\n'),
        messages: [{ role: 'user', content: userMsg }],
      });
      note.aiResponse = response.content[0]?.text?.trim() || null;
    } catch(e) { /* non-critical */ }
  }

  // Every note becomes a signal the AI can use (private/anonymous → inform-only).
  _emitSignalSafe(note.orgCode, {
    subjectType: 'member', subjectId: authorId, source: 'note',
    modality: 'text', label: note.tag || null, valueText: content,
    sensitivity: note.sensitivity,
  }, authorId);

  scheduleSave();
  res.json({ ok: true, note: _sanitizeNote(note, authorId) });
});

/* ── Get notes — requires auth ───────────────────────────────────────────── */
app.get('/api/notes', requireAuth, (req, res) => {
  const { groupId: gid, type } = req.query;
  // SECURITY: identity comes from the session, never the query. Previously
  // requesterId was read from the query, so any logged-in user could read
  // another member's PRIVATE notes by passing their id (IDOR). Fixed 2026-07-09.
  const code        = req.iqSession.orgCode;
  const requesterId = req.iqSession.userId;
  if (!code || !requesterId) return res.status(403).json({ error: 'Forbidden' });

  const myGroups = (orgGroups[code] || []).filter(g =>
    g.memberIds.includes(requesterId) || g.leadIds.includes(requesterId)
  ).map(g => g.id);

  const notes = Object.values(orgNotes)
    .filter(n => {
      if (n.orgCode !== code) return false;
      if (gid && n.groupId !== gid) return false;
      if (type && n.type !== type) return false;
      if (n.type === 'private') return n.authorId === requesterId;
      if (n.groupId) return myGroups.includes(n.groupId) || n.authorId === requesterId;
      return n.authorId === requesterId;
    })
    .map(n => _sanitizeNote(n, requesterId))
    .sort((a, b) => b.createdAt.localeCompare(a.createdAt));

  res.json({ notes });
});

function _sanitizeNote(note, requesterId) {
  if (note.type === 'anonymous' && note.authorId !== requesterId) {
    return { ...note, authorId: null, authorName: 'Anonymous' };
  }
  return note;
}

/* ── Delete own note ─────────────────────────────────────────────────────── */
app.delete('/api/notes/:noteId', (req, res) => {
  const { requesterId } = req.body;
  const note = orgNotes[req.params.noteId];
  if (!note) return res.status(404).json({ error: 'Note not found' });
  if (note.authorId !== requesterId) return res.status(403).json({ error: 'Not your note' });
  delete orgNotes[req.params.noteId];
  scheduleSave();
  res.json({ ok: true });
});

/* ═══════════════════════════════════════════════════════════════════════════
   PINNED + TEAM-SHARED NOTES (ai/notes) — a note is private by default; two
   deliberate, reversible acts change that: PIN it to a shelf you can return to, and
   SHARE it with the team. The privacy gate is the hard guard on sharing: a note it
   marked sensitive stays private even if the author asks. Scope follows the same node
   web as evidence/reasoning — a shared note reaches only teammates who can see the
   author's part of the org.
   ═══════════════════════════════════════════════════════════════════════════ */
function _noteById(code, id) { const n = orgNotes[id]; return (n && n.orgCode === code) ? n : null; }
// Can `userId` see this note? Its author always; a team-shared note only if the actor is
// within the author's visible scope (no cross-branch leak). Private notes: author only.
function _noteVisibleTo(code, userId, note) {
  if (!note) return false;
  if (note.authorId === userId) return true;
  if (!note.teamShared) return false;
  return orgGraph.canSee(_visibleScopeFor(code, userId), note.nodeScope || null);
}

app.post('/api/notes/:noteId/pin', requireAuth, (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  const note = _noteById(code, req.params.noteId);
  if (!note) return res.status(404).json({ ok: false, error: 'note_not_found' });
  if (!_noteVisibleTo(code, userId, note)) return res.status(403).json({ ok: false, error: 'forbidden' });
  Object.assign(note, noteGov.pin(note, { now: new Date().toISOString() }));
  scheduleSave();
  res.json({ ok: true, pinned: true });
});
app.post('/api/notes/:noteId/unpin', requireAuth, (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  const note = _noteById(code, req.params.noteId);
  if (!note) return res.status(404).json({ ok: false, error: 'note_not_found' });
  if (!_noteVisibleTo(code, userId, note)) return res.status(403).json({ ok: false, error: 'forbidden' });
  Object.assign(note, noteGov.unpin(note));
  scheduleSave();
  res.json({ ok: true, pinned: false });
});

/* Share with the team — author only, and only past the privacy gate. */
app.post('/api/notes/:noteId/share', requireAuth, (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  const note = _noteById(code, req.params.noteId);
  if (!note) return res.status(404).json({ ok: false, error: 'note_not_found' });
  if (note.authorId !== userId) return res.status(403).json({ ok: false, error: 'only_author_can_share' });
  const gate = noteGov.canShareToTeam(note, { isSensitive: privacy.isPrivate(note.sensitivity) });
  if (!gate.allowed) {
    return res.status(200).json({ ok: false, blocked: gate.reason,
      message: gate.reason === 'sensitive_stays_private'
        ? 'This note holds private context — it stays yours. It can’t be shared with the team.'
        : gate.reason === 'already_shared' ? 'This note is already shared with your team.'
        : 'This note can’t be shared.' });
  }
  Object.assign(note, noteGov.share(note, { actorId: userId, now: new Date().toISOString(), nodeScope: _primaryNodeScope(code, userId) }));
  _reasonNudge(code);   // new admissible input — let the next read re-reason
  scheduleSave();
  res.json({ ok: true, shared: true });
});
app.post('/api/notes/:noteId/unshare', requireAuth, (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  const note = _noteById(code, req.params.noteId);
  if (!note) return res.status(404).json({ ok: false, error: 'note_not_found' });
  if (note.authorId !== userId) return res.status(403).json({ ok: false, error: 'only_author_can_unshare' });
  Object.assign(note, noteGov.unshare(note));
  _reasonNudge(code);   // input withdrawn — let the next read re-reason without it
  scheduleSave();
  res.json({ ok: true, shared: false });
});

/* POST /api/notes/:id/ask — ask IntelliQ about a note you can see. The answer is grounded
   STRICTLY in that note's own words: the deterministic floor surfaces the note; when a key
   is present the model phrases a real answer, but the ONLY grounding it's given is this note
   — so a shared note can never pull in anything private. Visibility-gated like everything
   else. This is what turns a pinned team note into a living, askable artifact. */
app.post('/api/notes/:noteId/ask', requireAuth, async (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  const note = _noteById(code, req.params.noteId);
  if (!note) return res.status(404).json({ ok: false, error: 'note_not_found' });
  if (!_noteVisibleTo(code, userId, note)) return res.status(403).json({ ok: false, error: 'forbidden' });
  const question = String(req.body && req.body.question || '').slice(0, 500);
  if (!question.trim()) return res.status(400).json({ ok: false, error: 'question_required' });
  const g = noteGov.groundedAnswer(note, question);
  let answer = g.answer, enriched = false;
  if (ai.enabled()) {
    const p = ai.complete({
      tier: 'reason', maxTokens: 180,
      system: [
        'Answer the question USING ONLY the note below. If the note does not address it, say so plainly.',
        'Never invent facts beyond the note. Never predict what will happen, and never diagnose or name a condition — describe only what the note records. Two or three sentences, plain and honest.',
        _domainDirective(code),
      ].filter(Boolean).join('\n'),
      user: `Note: ${note.content}\n\nQuestion: ${question}`,
    });
    const out = await Promise.race([Promise.resolve(p).then(v => v, () => null), new Promise(r => setTimeout(() => r(null), AI_BRIEF_MS))]);
    // Grounded AND descriptive: reject any answer that predicts or diagnoses → keep the floor.
    if (out && String(out).trim() && languageGuard.describesOnly(out)) { answer = String(out).trim(); enriched = true; }
  }
  res.json({ ok: true, answer, grounded: true, relevant: g.relevant, enriched });
});

/* GET /api/notes/pinned — the shelf: your own pinned notes + team-shared pinned notes you
   can see, ordered pins-first. Each projected safely (a teammate's note never exposes its
   sensitivity, the author's private AI reply, or internal ids). */
app.get('/api/notes/pinned', requireAuth, (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  const all = Object.values(orgNotes).filter(n => n.orgCode === code && n.pinned);
  const rawMine = all.filter(n => n.authorId === userId);
  const rawTeam = all.filter(n => n.authorId !== userId && n.teamShared && _noteVisibleTo(code, userId, n));
  const mineIds = new Set(rawMine.map(n => n.id));
  const ordered = noteGov.shelfSort([...rawMine, ...rawTeam]);
  res.json({ ok: true, pinned: ordered.map(n => mineIds.has(n.id) ? noteGov.ownView(n) : noteGov.teamView(n)) });
});

/* ═══════════════════════════════════════════════════════════════════════════
   THE NODE-AWARE PROACTIVE BRIEF (ai/brief) — the assistant opening with a read AND
   governed offers, shaped by WHERE the person sits in the web. The web does four jobs
   here, then hands the results to the pure composer:
     • LEVEL   — org-graph.scopeOfActor → leader (aggregate) vs member (local)
     • SCOPE   — the same gate as evidence/reasoning picks the reads (no cross-branch leak)
     • AGGREGATE (leader) — a headline from the scoped agenda's own beliefs (composition,
                  never new reasoning)
     • ROUTE   (member) — org-graph.routeTarget (via _orgAskRouteLeader) → who can help
   brief.compose only ARRANGES; it never reasons or scopes. Every offer is proposal-gated. */
function _actorLevel(code, userId) {
  if (orgUsers[code]?.[userId]?.role === 'superadmin') return 'leader';
  const nodes = orgNodes[code];
  if (!nodes || !Object.keys(nodes).length) return _userHasPerm(code, userId, 'view_team') ? 'leader' : 'member';
  const { leaderNodeIds } = orgGraph.scopeOfActor(nodes, userId);
  return (leaderNodeIds && leaderNodeIds.length) ? 'leader' : 'member';
}
function _firstName(code, userId) { return String((orgUsers[code]?.[userId]?.name || '').split(/\s+/)[0] || ''); }
function _timeOfDay(now) { const h = new Date(now).getHours(); return h < 12 ? 'morning' : h < 18 ? 'afternoon' : 'evening'; }

app.get('/api/brief', requireAuth, async (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  try {
    const now = Date.now();
    const level = _actorLevel(code, userId);
    const practices = (orgPlaybook[code] || []).filter(e => e.status === 'active' && e.statement).slice(0, 3).map(e => e.statement);
    let reads = [], routeTo = null, rollupHeadline = null, areaLabel = _orgAskAreaLabel(code, userId);

    if (level === 'leader') {
      // SCOPE: the leader's own scoped agenda (a sibling branch never appears).
      const { agenda } = _reasonScopedAgenda(code, userId, now, false);
      reads = agenda.filter(a => a.readiness === 'ripe').map(a => ({ text: a.claim, meta: a.confidence, polarity: a.polarity }));
      // AGGREGATE: an honest headline composed from the beliefs already present (no new read).
      const prog = reads.filter(r => r.polarity === 'progress').length, risk = reads.filter(r => r.polarity === 'risk').length;
      if (prog > 0 && prog >= risk) rollupHeadline = `${areaLabel} has had a good week`;
    } else {
      // SCOPE: the member's OWN reads about themselves (their own evidence), never others'.
      reads = (reasonLedger[code] || [])
        .filter(b => b.subjectId === userId && !b.shared && _reasonReadableBelief(b, now))
        .map(b => { const v = reason.subjectView(b); return { text: _reasonDisclosureText(v.claim, b), meta: v.confidence, polarity: b.polarity }; });
      // ROUTE: who this member can turn to.
      const rt = _orgAskRouteLeader(code, userId);
      if (rt && rt.present && rt.label) routeTo = { label: rt.label };
    }

    // The caller's OWN accepted accommodations (self-model) — private to them, read back
    // here so an accepted proposal actually reshapes their brief. self_first is applied at
    // the server (lead with the person's own reads); the rest the brief composer honours.
    const habits = selfModel.learn({ priorHabits: selfModelLedger[_selfKey(code, userId)] || [], now });
    selfModelLedger[_selfKey(code, userId)] = habits;
    const prefs = selfModel.activeSettings(habits, now);
    if (prefs.self_first) {
      // The person likes to clear their own things first — put their own reads ahead of the rest.
      const ownReads = (reasonLedger[code] || [])
        .filter(b => b.subjectId === userId && !b.shared && _reasonReadableBelief(b, now))
        .map(b => { const v = reason.subjectView(b); return { text: _reasonDisclosureText(v.claim, b), meta: v.confidence, polarity: b.polarity, own: true }; });
      const already = new Set(reads.map(r => r.text));
      reads = [...ownReads.filter(r => !already.has(r.text)), ...reads];
    }

    const name = _firstName(code, userId), timeOfDay = _timeOfDay(now);
    const composed = brief.compose({ level, name, timeOfDay, reads, practices, routeTo, rollupHeadline, areaLabel, prefs });
    // The assistant speaks in OUR OWN voice (ai/voice) — deterministic, prediction-proof, no
    // model. It composes the opening from the same facts; nothing is invented or foretold.
    const opening = level === 'leader'
      ? voice.leaderOpening({ name, timeOfDay, count: reads.length, rollupHeadline, areaLabel, seed: userId + level })
      : voice.memberOpening({ name, timeOfDay, count: reads.length, seed: userId + level });
    res.json({ ok: true, level, opening, items: composed.items, offers: composed.offers, applied: composed.applied || [] });
  } catch (e) {
    console.warn('[brief] failed:', e && e.message);
    res.json({ ok: true, level: 'member', opening: 'Here’s where things stand.', items: [], offers: [] });
  }
});

/* ═══════════════════════════════════════════════════════════════════════════
   OUTBOUND DELIVERY (ai/delivery) — the last mile. IntelliQ reaches a person off-
   platform (web-push now; email/Slack later) with a governed, grounded, well-timed
   rundown — never a prediction, never a sensitive read, never spam. Consent-first
   (opt-in per person), org- and no-egress-gated, and every send is audit-logged.
   ═══════════════════════════════════════════════════════════════════════════ */

/* The reads a person's digest/alert may draw on — the SAME scoped, grounded reads the
   brief uses, each tagged with careFlag so the outbound gate can drop anything sensitive.
   Care-flag is resolved from the ledger and FAILS SAFE: an unresolvable belief is treated
   as sensitive and excluded, so a wellbeing read can never leak off-platform. */
function _deliveryReadsFor(code, userId, now) {
  const level = _actorLevel(code, userId);
  const name  = _firstName(code, userId);
  const ledger = reasonLedger[code] || [];
  const byId = new Map(ledger.map(b => [b.id, b]));
  const careOf = (item) => {
    if (item.rolled) return (item.memberBeliefIds || []).some(id => (byId.get(id) || {}).careFlag);
    const b = byId.get(item.beliefId);
    return b ? !!b.careFlag : true;                 // fail safe: unknown → sensitive → excluded
  };
  let reads = [];
  if (level === 'leader') {
    const { agenda } = _reasonScopedAgenda(code, userId, now, false);
    reads = agenda.map(a => ({ text: a.claim, readiness: a.readiness, urgency: a.urgency, careFlag: careOf(a) }));
  } else {
    reads = ledger
      .filter(b => b.subjectId === userId && !b.shared && _reasonReadableBelief(b, now))
      .map(b => { const v = reason.subjectView(b); return { text: _reasonDisclosureText(v.claim, b), readiness: b.readiness, urgency: b.urgency, careFlag: !!b.careFlag }; });
  }
  const timeOfDay = _timeOfDay(now);
  const nEligible = delivery.eligibleReads(reads).length;
  const opening = level === 'leader'
    ? voice.leaderOpening({ name, timeOfDay, count: nEligible, seed: userId + level })
    : voice.memberOpening({ name, timeOfDay, count: nEligible, seed: userId + level });
  return { level, name, opening, reads };
}

/* Compose one person's digest and (if the decision says so) deliver it. `force` bypasses the
   cadence/quiet-hours gate for an explicit self-test, but NEVER the privacy gate (sensitive
   reads are always excluded) or consent (a channel/subscription must exist to actually send).
   Returns what happened — the payload, whether it was sent, and how many pushes landed. */
async function _deliverDigest(code, userId, { force = false } = {}) {
  const now = Date.now();
  const key = userKey(code, userId);
  const prefs = { ...delivery.DEFAULT_PREFS, ...(deliveryPrefs[key] || {}) };
  const { name, opening, reads } = _deliveryReadsFor(code, userId, now);
  const eligible = delivery.eligibleReads(reads);
  const decision = force
    ? { send: eligible.length > 0 || true, reason: 'test' }
    : delivery.shouldDeliver({ prefs, now, hasContent: eligible.length > 0 });
  if (!decision.send) return { sent: false, reason: decision.reason };
  const payload = delivery.composeDigest({ name, opening, reads, url: '/' });
  const subs = pushSubs[key] || [];
  let delivered = 0, gone = [];
  for (const s of subs) {
    const r = await _sendPush(s, payload);
    if (r.ok) delivered++;
    else if (r.statusCode === 404 || r.statusCode === 410) gone.push(s.endpoint);   // subscription expired — prune
  }
  if (gone.length) { pushSubs[key] = subs.filter(s => !gone.includes(s.endpoint)); }
  prefs.lastSentAt = now;
  deliveryPrefs[key] = prefs;
  _audit(code, { actor: 'system', action: 'outbound_delivery', subjectIds: [userId], basis: `digest · ${payload.itemCount} item(s) · ${delivered}/${subs.length} push${force ? ' · test' : ''}` });
  scheduleSave();
  return { sent: true, payload, delivered, subscriptions: subs.length, channelReady: PUSH_READY };
}

/* The DELIVERY SWEEP — the heartbeat's outbound beat. For every org that permits outbound,
   every person opted in gets their digest considered (the gate decides if it actually goes).
   Bounded + per-person isolated: one failure never stops the rest. Returns how many sent. */
async function _deliverySweep() {
  let sent = 0;
  for (const code of Object.keys(orgUsers)) {
    if (!_outboundAllowed(code)) continue;
    for (const uid of Object.keys(orgUsers[code] || {})) {
      const key = userKey(code, uid);
      const p = deliveryPrefs[key];
      if (!p || !p.enabled) continue;                 // opt-in only
      try { const r = await _deliverDigest(code, uid, { force: false }); if (r.sent) sent++; }
      catch (e) { console.warn(`[delivery] sweep failed for ${code}:${uid}:`, e && e.message); }
    }
  }
  return sent;
}

/* GET /api/delivery/config — what the client needs to subscribe: whether push is live on
   this deployment, and the VAPID public key to register a subscription with. */
app.get('/api/delivery/config', requireAuth, (req, res) => {
  const { orgCode: code } = req.iqSession;
  res.json({ ok: true, pushReady: PUSH_READY, outboundAllowed: _outboundAllowed(code), vapidPublicKey: VAPID_PUBLIC || null });
});

/* GET/POST /api/delivery/prefs — a person's OWN delivery preferences (opt-in, channels,
   cadence, quiet hours, timezone). Strictly self. */
app.get('/api/delivery/prefs', requireAuth, (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  res.json({ ok: true, prefs: { ...delivery.DEFAULT_PREFS, ...(deliveryPrefs[userKey(code, userId)] || {}) }, outboundAllowed: _outboundAllowed(code) });
});
app.post('/api/delivery/prefs', requireAuth, (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  const key = userKey(code, userId);
  const cur = { ...delivery.DEFAULT_PREFS, ...(deliveryPrefs[key] || {}) };
  const b = req.body || {};
  const next = { ...cur };
  if (typeof b.enabled === 'boolean') next.enabled = b.enabled;
  if (b.channels && typeof b.channels === 'object') next.channels = { push: !!b.channels.push, email: !!b.channels.email };
  if (b.cadence === 'daily' || b.cadence === 'off') next.cadence = b.cadence;
  if (Number.isFinite(b.quietStart)) next.quietStart = Math.max(0, Math.min(23, Math.floor(b.quietStart)));
  if (Number.isFinite(b.quietEnd))   next.quietEnd   = Math.max(0, Math.min(23, Math.floor(b.quietEnd)));
  if (Number.isFinite(b.tzOffsetMin)) next.tzOffsetMin = Math.max(-840, Math.min(840, Math.floor(b.tzOffsetMin)));
  deliveryPrefs[key] = next;
  scheduleSave();
  res.json({ ok: true, prefs: next });
});

/* POST /api/delivery/subscribe — store a web-push subscription for the caller (self only).
   POST /api/delivery/unsubscribe — drop one by endpoint. */
app.post('/api/delivery/subscribe', requireAuth, (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  if (!_outboundAllowed(code)) return res.status(403).json({ ok: false, error: 'outbound_disabled' });
  const sub = req.body && req.body.subscription;
  if (!sub || !sub.endpoint || !sub.keys) return res.status(400).json({ ok: false, error: 'invalid_subscription' });
  const key = userKey(code, userId);
  const list = pushSubs[key] = (pushSubs[key] || []).filter(s => s.endpoint !== sub.endpoint);
  list.push({ endpoint: String(sub.endpoint).slice(0, 600), keys: { p256dh: String(sub.keys.p256dh || '').slice(0, 200), auth: String(sub.keys.auth || '').slice(0, 100) } });
  // Subscribing implies the person wants push on — turn the channel on (they can still tune).
  const prefs = deliveryPrefs[key] = { ...delivery.DEFAULT_PREFS, ...(deliveryPrefs[key] || {}) };
  prefs.enabled = true; prefs.channels = { ...prefs.channels, push: true };
  scheduleSave();
  res.json({ ok: true, subscriptions: list.length, pushReady: PUSH_READY });
});
app.post('/api/delivery/unsubscribe', requireAuth, (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  const key = userKey(code, userId);
  const endpoint = req.body && req.body.endpoint;
  if (endpoint) pushSubs[key] = (pushSubs[key] || []).filter(s => s.endpoint !== endpoint);
  else pushSubs[key] = [];
  scheduleSave();
  res.json({ ok: true, subscriptions: (pushSubs[key] || []).length });
});

/* GET /api/delivery/preview — the digest that WOULD be delivered right now, with the send
   decision (why it would or wouldn't go). No send, no side effects. Self only — proof to the
   person of exactly what leaves the box (and that nothing sensitive does). */
app.get('/api/delivery/preview', requireAuth, (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  const now = Date.now();
  const key = userKey(code, userId);
  const prefs = { ...delivery.DEFAULT_PREFS, ...(deliveryPrefs[key] || {}) };
  const { name, opening, reads } = _deliveryReadsFor(code, userId, now);
  const eligible = delivery.eligibleReads(reads);
  const payload = delivery.composeDigest({ name, opening, reads, url: '/' });
  const decision = delivery.shouldDeliver({ prefs, now, hasContent: eligible.length > 0 });
  const alertRead = delivery.alertWorthy(reads);
  res.json({ ok: true, payload, decision, wouldAlert: alertRead ? delivery.composeAlert({ name, read: alertRead, url: '/' }) : null, excludedSensitive: reads.length - eligible.length });
});

/* POST /api/delivery/test — send yourself one now (bypasses cadence/quiet hours, never the
   privacy gate). Requires a real subscription/channel to actually land. Self only. */
app.post('/api/delivery/test', requireAuth, async (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  if (!_outboundAllowed(code)) return res.status(403).json({ ok: false, error: 'outbound_disabled' });
  const r = await _deliverDigest(code, userId, { force: true });
  res.json({ ok: true, ...r });
});

/* GET /api/report/team — the first ARTIFACT: a grounded team report. Print-ready HTML the
   browser saves as a PDF, OR — with ?format=csv (or the /api/report/team.csv path) — the
   SAME grounded facts as a board-ready, spreadsheet-openable CSV. Both render only what the
   reasoner and the confirmed playbook already know — every line shows its source, and
   anything without one never appears (the ai/report grounding guarantee). Infrastructure,
   not UI: the assistant offers "want a report?"; this is what it links to. The CSV is the
   first paid-tier EXPORT — the same intelligence, in a format an org can hand to a board or
   drop in a spreadsheet. Leader-gated + scoped + audit-logged like everything else. */
app.get(['/api/report/team', '/api/report/team.csv'], requireAuth, (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  const isAdmin = orgUsers[code]?.[userId]?.role === 'superadmin';
  if (!isAdmin && !_userHasPerm(code, userId, 'view_team') && !_userHasPerm(code, userId, 'view_insights')) {
    return res.status(403).type('text/plain').send('Permission denied');
  }
  const asCsv = req.path.endsWith('.csv') || String(req.query.format || '').toLowerCase() === 'csv';
  const now = Date.now();
  let attention = [], practices = [];
  try {
    const { agenda } = _reasonScopedAgenda(code, userId, now, false);
    attention = agenda.filter(a => a.readiness === 'ripe').map(a => ({
      text: a.claim,
      basis: `reasoner · ${a.confidence}${a.reliability && a.reliability !== 'calibrating' ? ' · ' + a.reliability : ''}`,
    }));
  } catch (_) {}
  try {
    practices = (orgPlaybook[code] || []).filter(e => e.status === 'active' && e.statement)
      .map(e => ({ text: e.statement, basis: 'playbook · confirmed practice' }));
  } catch (_) {}
  const model = report.buildReport({
    title: 'Team report',
    subject: _orgAskAreaLabel(code, userId),
    generatedAt: new Date(now).toISOString(),
    intro: attention.length
      ? `${attention.length} thing${attention.length === 1 ? '' : 's'} the reasoner judges worth your attention — drawn only from recorded check-ins and evidence.`
      : 'A steady week — this reflects only what’s recorded.',
    sections: [
      { heading: 'Worth your attention', facts: attention, emptyNote: 'Nothing is pressing — no recorded pattern is strong enough to raise.' },
      { heading: 'Confirmed practices', facts: practices, emptyNote: 'No practices are confirmed into your playbook yet.' },
    ],
  });
  // ACCOUNTABILITY — rendering a grounded report about people is an accountable access.
  try {
    const { agenda } = _reasonScopedAgenda(code, userId, now, false);
    const touched = [...new Set(agenda.map(a => a.subjectId).filter(Boolean))];
    _audit(code, { actor: userId, action: 'report_view', subjectIds: touched, basis: asCsv ? 'grounded report export (CSV)' : 'grounded team report' });
  } catch (_) {}
  if (asCsv) {
    res.setHeader('Content-Type', 'text/csv; charset=utf-8');
    res.setHeader('Content-Disposition', 'attachment; filename="intelliq-team-report.csv"');
    return res.send(report.renderCsv(model));
  }
  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.send(report.renderHtml(model));
});

/* GET /api/report/person/:userId — a grounded PERSONAL development record. The artifact a
   coach hands a player, or a teacher a parent: everything the system can point to about ONE
   person — the reads the reasoner holds (person-safe, never the leader-facing urgency), and
   the strengths recorded from their own assessments — each line showing its source, nothing
   invented. HTML (→ PDF) or ?format=csv. Access is either the SUBJECT themselves (their own
   record) or a leader who may SEE them (visibility-scoped, view permission); anyone else is
   refused. Audit-logged as a report_view of that person — a per-person export is exactly the
   access a compliance trail must capture. This is a paid-tier artifact that reuses the whole
   grounded stack. */
app.get('/api/report/person/:userId', requireAuth, (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  let targetId = String(req.params.userId || '');
  // Support a clean .csv suffix on the id (…/person/joe.csv) as well as ?format=csv.
  let csvSuffix = false;
  if (targetId.endsWith('.csv')) { csvSuffix = true; targetId = targetId.slice(0, -4); }
  const target = orgUsers[code]?.[targetId];
  if (!target) return res.status(404).type('text/plain').send('Person not found');
  const isSelf   = targetId === userId;
  const isAdmin  = orgUsers[code]?.[userId]?.role === 'superadmin';
  const canView  = isAdmin || _userHasPerm(code, userId, 'view_team') || _userHasPerm(code, userId, 'view_insights');
  const inScope  = new Set(getVisibleUserIds(code, userId)).has(targetId);
  if (!isSelf && !(canView && inScope)) return res.status(403).type('text/plain').send('Permission denied');

  const asCsv = csvSuffix || String(req.query.format || '').toLowerCase() === 'csv';
  const now = Date.now();
  let reads = [], strengths = [];
  try {
    _reasonTick(code, now, false);
    reads = (reasonLedger[code] || [])
      // A shareable record: non-dormant, non-suppressed reads about them — and NOT a
      // care-flagged (sensitive wellbeing) read, which stays out of a handable artifact.
      .filter(b => b.subjectId === targetId && !b.shared && !b.careFlag && _reasonReadableBelief(b, now))
      .map(b => ({
        text: _reasonDisclosureText(b.claim, b),
        basis: `reasoner · ${b.confidence || 'tentative'}${b.status === 'contested' ? ' · contested — unresolved' : ''}`,
      }));
  } catch (_) {}
  try {
    strengths = (_personStrengths(code, targetId) || []).map(s => ({ text: `A recorded strength: ${s}.`, basis: 'assessment · recorded strength' }));
  } catch (_) {}

  const firstName = String(target.name || targetId).split(/\s+/)[0];
  const model = report.buildReport({
    title: `Development record — ${target.name || targetId}`,
    subject: isSelf ? 'Your own record' : (_orgAskAreaLabel(code, userId) || null),
    generatedAt: new Date(now).toISOString(),
    intro: `What the system can point to about ${firstName} — drawn only from recorded evidence, each line showing its source. Nothing here is invented or predicted.`,
    sections: [
      { heading: 'Where things stand', facts: reads, emptyNote: 'Nothing is currently strong enough to raise — a steady, unremarkable picture.' },
      { heading: 'Strengths recorded', facts: strengths, emptyNote: 'No strengths are recorded from assessments yet.' },
    ],
  });
  _audit(code, { actor: userId, action: 'report_view', subjectIds: [targetId], basis: isSelf ? 'own development record' : 'grounded person report' });
  if (asCsv) {
    res.setHeader('Content-Type', 'text/csv; charset=utf-8');
    res.setHeader('Content-Disposition', `attachment; filename="intelliq-${firstName.toLowerCase().replace(/[^a-z0-9]/g, '') || 'person'}-record.csv"`);
    return res.send(report.renderCsv(model));
  }
  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.send(report.renderHtml(model));
});

/* ═══════════════════════════════════════════════════════════════════════════
   THE SELF-MODEL (ai/self-model) — IntelliQ learning how YOU like to work and
   offering to fit itself around you. Strictly PRIVATE to the person: every route
   here reads and writes only the caller's OWN ledger (userKey). It never reports a
   person's habits to anyone, never evaluates them — it only proposes a convenience
   back, which the person confirms, dismisses, or rejects.
   ═══════════════════════════════════════════════════════════════════════════ */
const _selfKey = (code, userId) => userKey(code, userId);

/* POST /api/self/observe — record ONE interaction event about yourself. Only allow-listed
   patterns are learned (the module ignores anything else); a habit forms only across
   distinct days. This is the single write, and it's always about the caller. */
app.post('/api/self/observe', requireAuth, (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  const pattern = String(req.body && req.body.pattern || '');
  if (!selfModel.PATTERNS[pattern]) return res.status(200).json({ ok: true, ignored: true });   // not learnable → quietly ignored
  const label = req.body && req.body.label != null ? String(req.body.label) : '';
  const key = _selfKey(code, userId);
  selfModelLedger[key] = selfModel.learn({ priorHabits: selfModelLedger[key] || [], events: [{ pattern, label, t: Date.now() }], now: Date.now() });
  scheduleSave();
  res.json({ ok: true });
});

/* GET /api/self/patterns — what IntelliQ would offer to do for you (proposal-gated), plus
   full transparency into everything it has learned about your working habits. Self only. */
app.get('/api/self/patterns', requireAuth, (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  const now = Date.now();
  const habits = selfModel.learn({ priorHabits: selfModelLedger[_selfKey(code, userId)] || [], now });
  selfModelLedger[_selfKey(code, userId)] = habits;   // refresh statuses (staleness) in place
  res.json({ ok: true, proposals: selfModel.proposals(habits, now), learned: selfModel.selfView(habits) });
});

/* POST /api/self/:habitId/feedback — accept (apply it), dismiss (not now), or reject (not a
   thing I do). Your model, your call. Self only. */
app.post('/api/self/:habitId/feedback', requireAuth, (req, res) => {
  const { orgCode: code, userId } = req.iqSession;
  const response = String(req.body && req.body.response || '');
  if (!selfModel.RESPONSES.has(response)) return res.status(400).json({ ok: false, error: 'invalid_response' });
  const key = _selfKey(code, userId);
  const habits = selfModelLedger[key] || [];
  const h = selfModel.applyFeedback(habits, String(req.params.habitId || ''), response, Date.now());
  if (!h) return res.status(404).json({ ok: false, error: 'habit_not_found' });
  selfModelLedger[key] = habits;
  scheduleSave();
  res.json({ ok: true, habitId: h.id, response, setting: response === 'accept' ? (selfModel.PATTERNS[h.pattern] || {}).setting || null : null });
});

/* ═══════════════════════════════════════════════════════════════════════════
   MESSAGES — Known or Anonymous, to a person / group / org
   ═══════════════════════════════════════════════════════════════════════════ */

/* ── Send message ─────────────────────────────────────────────────────────── */
app.post('/api/messages/send', requireAuth, (req, res) => {
  // Sender identity is the SESSION, never the body — no sending as someone else / another org.
  const orgCode = req.iqSession.orgCode;
  const fromId = req.iqSession.userId;
  const fromName = orgUsers[orgCode]?.[fromId]?.name || '';
  const { toType, toId, content, anonymous } = req.body;
  if (!content || !toType) return res.status(400).json({ error: 'missing fields' });
  const id  = msgId();
  const msg = {
    id, orgCode: orgCode.toLowerCase().trim(),
    fromId, fromName: anonymous ? 'Anonymous' : fromName,
    _realFromId: fromId,
    toType, toId: toId || null,
    content, anonymous: !!anonymous,
    createdAt: new Date().toISOString(),
    readBy: [],
  };
  orgMessages[id] = msg;
  scheduleSave();
  res.json({ ok: true, messageId: id });
});

/* ── Get messages — requires auth ────────────────────────────────────────── */
app.get('/api/messages', requireAuth, (req, res) => {
  const { groupId: gid, toType } = req.query;
  // SECURITY: identity from the session, never the query — previously a
  // caller-supplied requesterId let any logged-in user read another member's
  // direct messages (IDOR). Fixed 2026-07-09.
  const code        = req.iqSession.orgCode;
  const requesterId = req.iqSession.userId;
  if (!code || !requesterId) return res.status(403).json({ error: 'Forbidden' });

  const myGroups = (orgGroups[code] || []).filter(g =>
    g.memberIds.includes(requesterId) || g.leadIds.includes(requesterId)
  ).map(g => g.id);

  const msgs = Object.values(orgMessages)
    .filter(m => {
      if (m.orgCode !== code) return false;
      if (gid && m.toId !== gid) return false;
      if (toType && m.toType !== toType) return false;
      if (m._realFromId === requesterId) return true;
      if (m.toType === 'user' && m.toId === requesterId) return true;
      if (m.toType === 'group' && myGroups.includes(m.toId)) return true;
      if (m.toType === 'org' && m.orgCode === code) return true;
      return false;
    })
    .map(m => _sanitizeMsg(m, requesterId))
    .sort((a, b) => b.createdAt.localeCompare(a.createdAt));

  res.json({ messages: msgs });
});

/* ── Mark message read ───────────────────────────────────────────────────── */
app.post('/api/messages/:msgId/read', (req, res) => {
  const { requesterId } = req.body;
  const m = orgMessages[req.params.msgId];
  if (!m) return res.status(404).json({ error: 'Not found' });
  if (!m.readBy.includes(requesterId)) m.readBy.push(requesterId);
  scheduleSave();
  res.json({ ok: true });
});

function _sanitizeMsg(msg, requesterId) {
  if (msg.anonymous && msg._realFromId !== requesterId) {
    const { _realFromId, ...safe } = msg;
    return safe;
  }
  const { _realFromId, ...safe } = msg;
  return safe;
}

/* ── Group feed (shared + anonymous notes + messages) ────────────────────── */
app.get('/api/groups/:groupId/feed', requireAuth, (req, res) => {
  // SECURITY: identity from the session, never the query. Was unauthenticated and
  // trusted a caller-supplied requesterId for group-membership checks (IDOR).
  const code        = req.iqSession.orgCode;
  const requesterId = req.iqSession.userId;
  if (!code || !requesterId) return res.status(403).json({ error: 'Forbidden' });
  const gid  = req.params.groupId;

  const groups = orgGroups[code] || [];
  const group  = groups.find(g => g.id === gid);
  if (group) {
    const isMemberOrLead = group.memberIds.includes(requesterId) || group.leadIds.includes(requesterId);
    const users = orgUsers[code] || {};
    const requesterUser = users[requesterId];
    const isOrgStaff = requesterUser && ['superadmin','admin','coach'].includes(requesterUser.role);
    if (!isMemberOrLead && !isOrgStaff) {
      return res.status(403).json({ error: 'Not a member of this group' });
    }
  }

  const notes = Object.values(orgNotes)
    .filter(n => n.orgCode === code && n.groupId === gid && (n.type === 'shared' || n.type === 'anonymous'))
    .map(n => _sanitizeNote(n, requesterId))
    .sort((a,b) => b.createdAt.localeCompare(a.createdAt));

  const messages = Object.values(orgMessages)
    .filter(m => m.orgCode === code && m.toType === 'group' && m.toId === gid)
    .map(m => _sanitizeMsg(m, requesterId))
    .sort((a,b) => b.createdAt.localeCompare(a.createdAt));

  res.json({ notes, messages });
});


/* ═══════════════════════════════════════════════════════════════════════════
   MEMBER APP — SHARED SESSION STORE
   ═══════════════════════════════════════════════════════════════════════════ */

const orgStore          = {};  // populated at startup via _loadAllStores()
const assignedScenarios = {};
const memberResults     = {};
const memberCheckins    = {};
const orgInterventions  = {};  // orgCode → [intervention, ...]
const advisorThreads    = {};  // orgCode → [{ id, memberId, requesterId, requesterRole, question, answer, evidence, createdAt }]

/* ═══════════════════════════════════════════════════════════════════════════
   UNIVERSAL SIGNAL INGESTION  (the input layer)
   Product thesis: the more input the ecosystem ingests, the stronger the output.
   Every input — check-in, voice film note, spreadsheet row, game stat, coach
   observation, or an external feed (Teams / Google / Outlook) — normalises into
   ONE Signal shape that the AI (Advisor, Group Copilot, memory) reasons over.
   Sources are a registry so new connectors plug in without touching the core.
   ═══════════════════════════════════════════════════════════════════════════ */
const orgSignals = {};  // orgCode → [ signal ]

/* Source registry — declares known/plannable input sources + their defaults.
   `integration:true` sources are OAuth connectors (built later) but the contract
   is here now so the rest of the system can already reason about them. */
const SIGNAL_SOURCES = {
  checkin:   { label: 'Check-in',           modality: 'text',   defaultSensitivity: 'sensitive' },
  note:      { label: 'Note / observation', modality: 'text',   defaultSensitivity: 'normal' },
  assessment:{ label: 'Assessment',         modality: 'text',   defaultSensitivity: 'normal' },
  weekly:    { label: 'Weekly reflection',  modality: 'text',   defaultSensitivity: 'sensitive' },
  voice:     { label: 'Voice note',         modality: 'audio',  defaultSensitivity: 'normal' },
  film:      { label: 'Film note',          modality: 'text',   defaultSensitivity: 'normal' },
  metric:    { label: 'Metric',             modality: 'number', defaultSensitivity: 'normal' },
  sheet:     { label: 'Spreadsheet row',    modality: 'sheet',  defaultSensitivity: 'normal' },
  gamestats: { label: 'Game stats',         modality: 'number', defaultSensitivity: 'public' },
  document:  { label: 'Document',           modality: 'file',   defaultSensitivity: 'normal' },
  external:  { label: 'External feed',      modality: 'data',   defaultSensitivity: 'normal' },
  teams:     { label: 'Microsoft Teams',    modality: 'event',  defaultSensitivity: 'normal', integration: true },
  google:    { label: 'Google Workspace',   modality: 'event',  defaultSensitivity: 'normal', integration: true },
  outlook:   { label: 'Outlook / Email',    modality: 'event',  defaultSensitivity: 'normal', integration: true },
};

function signalId() { return 'sig_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7); }

/* ── Signal weighting — not everything is equally important ────────────────────
   STRONG  : assessment results, metrics, game stats, stat sheets (hard outcomes)
   MEDIUM  : reflections, notes, check-ins, film/voice/document
   WEAK    : one-off external events / messages / comments
   Effective weight also rises with REPETITION (repeated behaviour) and RECENCY,
   so a recurring pattern outweighs a single strong data point. Keeps the AI from
   treating one stray note like a season of results. */
const SIGNAL_WEIGHTS = {
  assessment: 3, metric: 3, gamestats: 3, sheet: 3,
  weekly: 2, note: 2, checkin: 2, film: 2, document: 2, voice: 2,
  external: 1, teams: 1, google: 1, outlook: 1,
};
function _signalBaseWeight(source) { return SIGNAL_WEIGHTS[source] != null ? SIGNAL_WEIGHTS[source] : 1; }
function _weightTier(n) { return n >= 3 ? 'strong' : n >= 2 ? 'medium' : 'weak'; }

/* Normalise + store one raw signal. Returns the stored signal (or null if invalid). */
function _ingestSignal(code, raw, createdBy) {
  if (!raw || !raw.source) return null;
  const src = SIGNAL_SOURCES[raw.source] || { modality: 'data', defaultSensitivity: 'normal' };
  const text = raw.valueText != null ? String(raw.valueText) : '';
  const sensitivity = raw.public ? 'public'
    : raw.sensitivity || (text ? privacy.classifyText(text, { source: raw.source }) : src.defaultSensitivity);
  const sig = {
    id:          signalId(),
    orgCode:     code,
    ts:          raw.ts || new Date().toISOString(),
    source:      raw.source,
    modality:    raw.modality || src.modality || 'data',
    subjectType: raw.subjectType || 'member',     // member | group | org
    subjectId:   raw.subjectId || null,
    category:    raw.category || null,            // perf-framework category (optional)
    label:       raw.label != null ? String(raw.label).slice(0, 120) : null,
    valueNum:    raw.valueNum != null && !isNaN(Number(raw.valueNum)) ? Number(raw.valueNum) : null,
    valueText:   text.slice(0, 4000) || null,
    data:        raw.data || null,                // structured payload (sheet row, event, etc.)
    sensitivity,
    public:      sensitivity === 'public',
    weightNum:   raw.weightNum != null ? raw.weightNum : _signalBaseWeight(raw.source),
    weight:      _weightTier(raw.weightNum != null ? raw.weightNum : _signalBaseWeight(raw.source)),
    createdBy:   createdBy || null,
    createdAt:   new Date().toISOString(),
  };
  if (!orgSignals[code]) orgSignals[code] = [];
  orgSignals[code].push(sig);
  return sig;
}

/* Resolve a userId from a member name within an org (best-effort). */
function _resolveUserIdByName(code, name) {
  if (!name) return null;
  const n = String(name).toLowerCase().trim();
  const u = Object.values(orgUsers[code] || {}).find(u => (u.name || '').toLowerCase().trim() === n);
  return u ? u.id : null;
}

/* Emit a signal from an input touchpoint — never throws (input flow must not
   break if signal capture fails). This is how EVERY input becomes signal. */
function _emitSignalSafe(code, raw, createdBy) {
  try {
    const r = _ingestSignal(code, raw, createdBy);
    // AMBIENT SENSING — a new signal is new reality. Nudge the reasoner so the next read
    // re-reasons WITH it, instead of waiting for the 30-min heartbeat. Cheap (cache clear).
    _reasonNudge(code);
    return r;
  } catch (e) { console.warn('[signal] emit failed:', e.message); return null; }
}

/* Recent signals for a subject (used by the AI layer). */
function _gatherSignals(code, subjectType, subjectId, limit = 40) {
  return (orgSignals[code] || [])
    .filter(s => s.subjectType === subjectType && (subjectId == null || s.subjectId === subjectId))
    .sort((a, b) => new Date(b.ts) - new Date(a.ts))
    .slice(0, limit);
}

// Key helpers — new code uses userId keys; legacy name keys still supported for reads
function memberKey(orgCode, memberName) {
  return `${orgCode.toLowerCase().trim()}:${memberName.toLowerCase().trim()}`;
}
function userKey(orgCode, userId) {
  return `${orgCode.toLowerCase().trim()}:${userId}`;
}

/* ── Platform registers org ─────────────────────────────────────────────── */
app.post('/api/platform/register-org', (req, res) => {
  const { orgCode, orgName, orgMode } = req.body;
  if (!orgCode) return res.status(400).json({ error: 'orgCode required' });
  orgStore[orgCode.toLowerCase().trim()] = { orgName, orgMode };
  scheduleSave();
  res.json({ ok: true });
});

/* ── Update org mode ────────────────────────────────────────────────────── */
app.post('/api/platform/update-org-mode', requireAuth, (req, res) => {
  const { orgCode, orgMode } = req.body;
  if (!orgCode || !orgMode) return res.status(400).json({ error: 'orgCode and orgMode required' });
  const code = orgCode.toLowerCase().trim();
  if (orgMeta[code]) { orgMeta[code].orgMode = orgMode; scheduleSave(); }
  if (orgStore[code]) { orgStore[code].orgMode = orgMode; scheduleSave(); }
  res.json({ ok: true });
});

/* ── Bulk import users (CSV/XLSX parsed client-side) ─────────────────── */
app.post('/api/auth/bulk-import', requireAuth, async (req, res) => {
  const { orgCode, users: importRows } = req.body;
  if (!orgCode || !Array.isArray(importRows)) return res.status(400).json({ error: 'orgCode and users[] required' });
  const code    = orgCode.toLowerCase().trim();
  const creator = req.user;

  if (!orgUsers[code]) return res.status(404).json({ error: 'Org not found' });

  const created = [], skipped = [], failed = [];

  for (const row of importRows) {
    const name  = (row.name  || '').trim();
    const email = (row.email || '').trim().toLowerCase();
    const role  = (['admin','coach','member'].includes(row.role?.toLowerCase()) ? row.role.toLowerCase() : 'member');
    const group = (row.group || row.department || '').trim();

    if (!name) { failed.push({ row, reason: 'Missing name' }); continue; }
    if (!email) { failed.push({ row, reason: 'Missing email' }); continue; }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { failed.push({ row: name, reason: 'Invalid email format' }); continue; }

    // Check for duplicate by email (global) or name (org)
    if (emailIndex[email]) { skipped.push(`${name} (email already used)`); continue; }
    const existing = Object.values(orgUsers[code]).find(u => u.name.toLowerCase() === name.toLowerCase());
    if (existing) { skipped.push(name); continue; }

    const userId = generateId();
    const password = name.toLowerCase().replace(/\s+/g, '');
    const passwordHash = await bcrypt.hash(password, SALT_ROUNDS);
    const roleLevel = { admin: 2, coach: 3, member: 4 };
    // Parse firstName/lastName from name or explicit columns
    const fName = (row.firstName || name.split(' ')[0] || '').trim();
    const lName = (row.lastName  || name.split(' ').slice(1).join(' ') || '').trim();

    orgUsers[code][userId] = {
      id: userId,
      firstName: fName, lastName: lName,
      name, email, role, orgCode: code,
      group, department: group,
      passwordHash, passwordSet: false,
      status: 'active',
      createdAt: new Date().toISOString(),
      levelId: roleLevel[role] || 4,
      supervisorId: req.iqSession.userId,
      importedAt: new Date().toISOString(),
    };
    emailIndex[email] = { orgCode: code, userId };

    // Auto-create group if it doesn't exist
    if (group) {
      if (!orgGroups[code]) orgGroups[code] = [];
      const groupExists = orgGroups[code].some(g => g.name.toLowerCase() === group.toLowerCase());
      if (!groupExists) {
        orgGroups[code].push({
          id: generateId(), name: group, orgCode: code,
          memberIds: [], createdAt: new Date().toISOString(),
        });
      }
      // Add member to group
      const gObj = orgGroups[code].find(g => g.name.toLowerCase() === group.toLowerCase());
      if (gObj && !gObj.memberIds.includes(userId)) gObj.memberIds.push(userId);
    }

    created.push({ id: userId, name, role, group });
  }

  scheduleSave();
  res.json({ ok: true, created, skipped, failed, total: importRows.length });
});

/* ── List active join/invite links ───────────────────────────────────── */
app.get('/api/auth/join-links', requireAuth, (req, res) => {
  // SECURITY: invite links grant org access (at a role) — admin-only, own org.
  // Was gated on requireAuth only, exposing them to any authenticated user.
  const code   = req.iqSession.orgCode;
  const userId = req.iqSession.userId;
  const role   = orgUsers[code]?.[userId]?.role;
  if (!code || !(role === 'superadmin' || role === 'admin' || _userHasPerm(code, userId, 'manage_settings'))) {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }
  const now   = Date.now();
  const links = Object.entries(inviteTokens)
    .filter(([, t]) => t.orgCode === code && t.expiresAt > now)
    .map(([token, t]) => ({
      token,
      url:        `/?invite=${token}`,
      role:       t.role,
      group:      t.group || '',
      label:      t.label || '',
      usageLimit: t.usageLimit || null,
      useCount:   t.useCount || 0,
      expiresAt:  new Date(t.expiresAt).toISOString(),
      createdAt:  t.createdAt || null,
    }));
  res.json({ links });
});

